import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

type Fraction struct{ N, D int64 }

func fraction(n, d int64) Fraction {
	if n == 0 {
		return Fraction{0, 1}
	}
	if d < 0 {
		n = -n
		d = -d
	}
	a, b := n, d
	if a < 0 {
		a = -a
	}
	for b != 0 {
		a, b = b, a%b
	}
	return Fraction{n / a, d / a}
}
func integer(n int64) Fraction { return Fraction{n, 1} }
func (a Fraction) denominator() int64 {
	if a.D == 0 {
		return 1
	}
	return a.D
}
func (a Fraction) add(b Fraction) Fraction {
	return fraction(a.N*b.denominator()+b.N*a.denominator(), a.denominator()*b.denominator())
}
func (a Fraction) sub(b Fraction) Fraction { return a.add(b.neg()) }
func (a Fraction) mul(b Fraction) Fraction { return fraction(a.N*b.N, a.denominator()*b.denominator()) }
func (a Fraction) div(b Fraction) Fraction { return fraction(a.N*b.denominator(), a.denominator()*b.N) }
func (a Fraction) neg() Fraction           { return fraction(-a.N, a.denominator()) }
func (a Fraction) abs() Fraction {
	if a.N < 0 {
		return a.neg()
	}
	return a
}
func (a Fraction) cmp(b Fraction) int {
	left, right := a.N*b.denominator(), b.N*a.denominator()
	if left < right {
		return -1
	}
	if left > right {
		return 1
	}
	return 0
}
func (a Fraction) floor() int64 {
	d := a.denominator()
	q := a.N / d
	if a.N < 0 && a.N%d != 0 {
		q--
	}
	return q
}
func (a Fraction) ceil() int64 { return -a.neg().floor() }
func (a Fraction) whole() bool { return a.denominator() == 1 }
func (a Fraction) String() string {
	if a.denominator() == 1 {
		return strconv.FormatInt(a.N, 10)
	}
	return fmt.Sprintf("%d/%d", a.N, a.denominator())
}
func (a Fraction) approx() string {
	n := a.N
	if n < 0 {
		n = -n
	}
	d := a.denominator()
	t := (2*n*1000000 + d) / (2 * d)
	sign := ""
	if a.N < 0 && t > 0 {
		sign = "-"
	}
	return fmt.Sprintf("%s%d.%06d", sign, t/1000000, t%1000000)
}

var numberPattern = regexp.MustCompile(`^[0-9]+(?:\.[0-9]+|/[0-9]+)?$`)

func readNumber(word string, signed bool) (Fraction, bool) {
	sign := int64(1)
	if signed && strings.HasPrefix(word, "-") {
		sign = -1
		word = word[1:]
	}
	if !numberPattern.MatchString(word) {
		return Fraction{}, false
	}
	if strings.Contains(word, "/") {
		a := strings.Split(word, "/")
		n, _ := strconv.ParseInt(a[0], 10, 64)
		d, _ := strconv.ParseInt(a[1], 10, 64)
		if d == 0 {
			return Fraction{}, false
		}
		return fraction(sign*n, d), true
	}
	if strings.Contains(word, ".") {
		a := strings.Split(word, ".")
		n, _ := strconv.ParseInt(a[0]+a[1], 10, 64)
		d := int64(1)
		for range a[1] {
			d *= 10
		}
		return fraction(sign*n, d), true
	}
	n, _ := strconv.ParseInt(word, 10, 64)
	return integer(sign * n), true
}
func finite(value Fraction) *Fraction {
	copy := value
	return &copy
}
func boundText(value *Fraction, lower bool) string {
	if value != nil {
		return value.String()
	}
	if lower {
		return "-inf"
	}
	return "inf"
}

package main

import "fmt"

type PhaseResult struct {
	Iterations, Entering int
	Lines                []string
}

func phase(tableau *Tableau, cost []Fraction, candidates []bool, columns, rows []string, objective func(Fraction) Fraction) PhaseResult {
	result := PhaseResult{Entering: -1}
	for {
		reduced, _ := tableau.reduced(cost)
		q := -1
		for k, value := range reduced {
			if candidates[k] && value.N < 0 {
				q = k
				break
			}
		}
		if q < 0 {
			return result
		}
		p := -1
		ratio := integer(0)
		for i, row := range tableau.T {
			if row[q].N <= 0 {
				continue
			}
			value := tableau.Beta[i].div(row[q])
			if p < 0 || value.cmp(ratio) < 0 || value.cmp(ratio) == 0 && tableau.Basis[i] < tableau.Basis[p] {
				p = i
				ratio = value
			}
		}
		if p < 0 {
			result.Entering = q
			return result
		}
		leave := tableau.Basis[p]
		before := reduced[q]
		tableau.pivot(p, q)
		result.Iterations++
		_, z := tableau.reduced(cost)
		result.Lines = append(result.Lines, fmt.Sprintf("PIVOT %d enter %s reduced %s leave %s row %s ratio %s objective %s", result.Iterations, columns[q], before, columns[leave], rows[p], ratio, objective(z)))
	}
}

package main

import (
	"fmt"
	"strings"
)

type Tableau struct {
	T     [][]Fraction
	Beta  []Fraction
	Basis []int
}

func (t *Tableau) reduced(cost []Fraction) ([]Fraction, Fraction) {
	r := append([]Fraction{}, cost...)
	z := integer(0)
	for i, basic := range t.Basis {
		z = z.add(cost[basic].mul(t.Beta[i]))
		for k := range r {
			r[k] = r[k].sub(cost[basic].mul(t.T[i][k]))
		}
	}
	return r, z
}
func (t *Tableau) pivot(p, q int) {
	factor := t.T[p][q]
	for k := range t.T[p] {
		t.T[p][k] = t.T[p][k].div(factor)
	}
	t.Beta[p] = t.Beta[p].div(factor)
	for i := range t.T {
		if i == p {
			continue
		}
		f := t.T[i][q]
		for k := range t.T[i] {
			t.T[i][k] = t.T[i][k].sub(f.mul(t.T[p][k]))
		}
		t.Beta[i] = t.Beta[i].sub(f.mul(t.Beta[p]))
	}
	t.Basis[p] = q
}
func (t *Tableau) display(heading string, columns, rows []string, cost []Fraction, constant Fraction, sign int) []string {
	out := []string{"TABLEAU " + heading, "COLUMNS " + strings.Join(columns, " ")}
	for i, row := range t.T {
		values := []string{}
		for _, value := range row {
			values = append(values, value.String())
		}
		out = append(out, fmt.Sprintf("ROW %s %s %s | %s", rows[i], columns[t.Basis[i]], strings.Join(values, " "), t.Beta[i]))
	}
	reduced, z := t.reduced(cost)
	values := []string{}
	for _, value := range reduced {
		values = append(values, value.String())
	}
	out = append(out, fmt.Sprintf("COST %s | %s", strings.Join(values, " "), constant.add(integer(int64(sign)).mul(z))))
	return out
}
